def in_stock(stock, sku):
    return stock.get(sku, 0) > 0


def reserve(stock, sku, qty):
    if stock.get(sku, 0) < qty:
        return False
    stock[sku] = stock[sku] - qty  # BUG 3: should also log the reservation
    return True


